// @narra-notch-plugin 3
// Auto-generated by narra-notch. Install/uninstall from Settings → Coding Agent.
//
// Streams OpenCode session activity into the narra-notch named pipe so the
// desktop notch and the iPhone/PWA companion can show live tool activity.
//
// Since OpenCode V2 defaults to an allow-all policy, the plugin also asks the
// notch (GetRuntimeConfig) and, while approvals are enabled there, appends
// session-scoped `ask` rules for shell and file edits. That turn-on happens per
// session and never edits the user's opencode.json, so a fresh install needs no
// configuration; an explicit `deny` in the user's rules still wins.
//
// Approvals are resolved in the `permission.evaluate` hook: the notch answers
// *before* OpenCode publishes its own prompt, so the terminal never shows a
// second prompt after the notch/iPhone already allowed the action. Older
// servers without that hook fall back to relaying `permission.asked`.
//
// If narra-notch is not running, every call fails fast, no rules are injected,
// and OpenCode keeps its normal terminal behaviour. The plugin never throws
// into OpenCode.

import { connect } from "node:net"

const PIPE_PATH = process.env.NARRA_NOTCH_PIPE || "\\\\.\\pipe\\narra_notch_agent"
const SOURCE = "opencode"
const PROBE_TIMEOUT_MS = 1_200
const APPROVAL_TIMEOUT_MS = 60_000
const AUTO_REPLY_SETTLE_MS = 700
const CONFIG_TTL_MS = 5_000

type Decision = "allow" | "deny" | "always"

function text(value: unknown): string | undefined {
  return typeof value === "string" && value.length > 0 ? value : undefined
}

function call(event: string, payload: Record<string, unknown>, timeoutMs = PROBE_TIMEOUT_MS): Promise<any> {
  return new Promise((resolve) => {
    let settled = false
    let socket: any
    let buffer = ""

    const finish = (value: any) => {
      if (settled) return
      settled = true
      clearTimeout(timer)
      try {
        socket?.destroy()
      } catch {}
      resolve(value)
    }

    const timer = setTimeout(() => finish(null), timeoutMs)
    if (typeof (timer as any).unref === "function") (timer as any).unref()

    try {
      socket = connect(PIPE_PATH)
    } catch {
      finish(null)
      return
    }

    socket.on("connect", () => {
      try {
        socket.write(
          JSON.stringify({ event, source: SOURCE, payload, cwd: process.cwd() }) + "\n"
        )
      } catch {
        finish(null)
      }
    })

    socket.on("data", (chunk: any) => {
      buffer += chunk.toString("utf8")
      const newline = buffer.indexOf("\n")
      if (newline === -1) return
      const line = buffer.slice(0, newline).trim()
      if (!line) {
        finish(true)
        return
      }
      try {
        finish(JSON.parse(line))
      } catch {
        finish(true)
      }
    })

    socket.on("error", () => finish(null))
    socket.on("close", () => finish(null))
  })
}

/** Map OpenCode tool input onto the field names the notch already understands. */
function normalizeInput(input: any): Record<string, unknown> {
  const raw = input && typeof input === "object" ? input : {}
  const out: Record<string, unknown> = { ...raw }
  const path = text(raw.filePath) ?? text(raw.path) ?? text(raw.file_path)
  if (path) {
    out.Path = path
    out.path = path
    out.file_path = path
  }
  if (text(raw.command)) out.CommandLine = raw.command
  if (typeof raw.oldString === "string") out.Target = raw.oldString
  if (typeof raw.newString === "string") out.Replacement = raw.newString
  if (typeof raw.content === "string") out.Content = raw.content
  if (text(raw.pattern)) out.query = raw.pattern
  if (text(raw.url)) out.query = raw.url
  return out
}

function permissionDetails(action: string, resources: string[]) {
  const joined = resources.join(" · ")
  return joined ? `${action}: ${joined}` : `${action} requires approval`
}

/**
 * Session-scoped rules that ask the notch before shell commands and file edits.
 * They are appended after OpenCode's own rules (the last match wins), so they
 * override the default allow-all policy without touching opencode.json. A
 * `deny` from the user's rules still wins, and OpenCode's own "Allow always"
 * keeps saving project rules as usual.
 */
const ASK_RULES = [
  { action: "shell", resource: "*", effect: "ask" },
  { action: "edit", resource: "*", effect: "ask" },
  { action: "shell", resource: "git status *", effect: "allow" },
  { action: "shell", resource: "git diff *", effect: "allow" },
  { action: "shell", resource: "git log *", effect: "allow" },
]
const ASK_ACTIONS = new Set(["shell", "edit"])

const ruleKey = (rule: any) =>
  `${String(rule?.action ?? "")}\u0000${String(rule?.resource ?? "")}\u0000${String(rule?.effect ?? "")}`
const ourRuleKeys = new Set(ASK_RULES.map(ruleKey))
const ourAskKeys = new Set(ASK_RULES.filter((rule) => rule.effect === "ask").map(ruleKey))

/**
 * Keep user rules untouched, replace only our own rules, and place "always"
 * allow rules after the wildcard `ask` so a remembered approval actually wins.
 */
function mergeRules(existing: any[]): any[] {
  const seen = new Set<string>()
  const before: any[] = []
  const allowForAsk: any[] = []

  for (const rule of existing) {
    if (!rule || typeof rule !== "object") continue
    const key = ruleKey(rule)
    if (ourRuleKeys.has(key) || seen.has(key)) continue
    seen.add(key)
    if (ASK_ACTIONS.has(String(rule?.action ?? "")) && rule?.effect === "allow") allowForAsk.push(rule)
    else before.push(rule)
  }

  return [...before, ...ASK_RULES, ...allowForAsk]
}

const injectedSessions = new Set<string>()
const injectingSessions = new Set<string>()

const configCache = { at: 0, available: false, enabled: false }

/** Ask the notch whether approvals are on (cached briefly: one pipe call per 5 s). */
async function runtimeConfig() {
  if (Date.now() - configCache.at < CONFIG_TTL_MS) return configCache
  const config = await call("GetRuntimeConfig", {})
  configCache.at = Date.now()
  configCache.available = Boolean(config)
  configCache.enabled = Boolean(config) && config.askPermissions !== false
  return configCache
}

/**
 * Turn the session-scoped `ask` rules on or off to match the notch setting.
 * `null` from GetRuntimeConfig means the notch is not running, so the session
 * is left exactly as it is and OpenCode keeps its normal behaviour.
 */
async function syncSessionPermissions(ctx: any, sessionID: string) {
  if (!sessionID || injectingSessions.has(sessionID)) return
  injectingSessions.add(sessionID)
  try {
    const config = await runtimeConfig()
    if (!config.available) return

    const enabled = config.enabled
    if (enabled === injectedSessions.has(sessionID)) return

    let existing: any[] = []
    try {
      const session = await ctx.session.get({ sessionID })
      if (Array.isArray(session?.permissions)) existing = session.permissions
    } catch {}

    const permissions = enabled
      ? mergeRules(existing)
      : existing.filter((rule: any) => !ourRuleKeys.has(ruleKey(rule)))

    await ctx.session.update({ sessionID, permissions })
    if (enabled) injectedSessions.add(sessionID)
    else injectedSessions.delete(sessionID)
  } catch {
    // Older server without session rules: approvals simply stay off.
  } finally {
    injectingSessions.delete(sessionID)
  }
}

/** Remember "Always" for this session so the same action is not asked again. */
async function rememberAlways(ctx: any, sessionID: string, action: string, resources: string[]) {
  if (!resources.length) return
  try {
    const session = await ctx.session.get({ sessionID })
    const existing = Array.isArray(session?.permissions) ? session.permissions : []
    const additions = resources.map((resource) => ({ action, resource, effect: "allow" }))
    await ctx.session.update({ sessionID, permissions: mergeRules([...existing, ...additions]) })
    injectedSessions.add(sessionID)
  } catch {}
}

/** Relay one approval to the notch and return the user's decision, if any. */
async function askNotch(
  sessionID: string,
  action: string,
  resources: string[],
  sourceID?: string
): Promise<Decision | undefined> {
  // The source id identifies one tool call; both plugin instances produce the
  // same key, so the notch only opens one prompt for it.
  const requestKey = `${sessionID}|${action}|${sourceID ?? resources.join("|")}`
  const response = await call(
    "ApprovalRequest",
    {
      conversationId: sessionID,
      requestKey,
      toolName: action,
      details: permissionDetails(action, resources),
    },
    APPROVAL_TIMEOUT_MS
  )
  return text(response?.decision) as Decision | undefined
}

/** Legacy fallback for servers without the `permission.evaluate` hook. */
async function relayApproval(ctx: any, data: any, sessionID: string | undefined) {
  const requestID = text(data?.id) ?? text(data?.requestID)
  if (!requestID || !sessionID) return

  const config = await runtimeConfig()
  if (!config.available || !config.enabled) return

  // OpenCode publishes permission.asked even when config auto-allows it, then
  // replies immediately. Give auto replies a moment and skip those requests.
  await new Promise((resolve) => setTimeout(resolve, AUTO_REPLY_SETTLE_MS))
  try {
    const pending = await ctx.permission.list({ sessionID })
    const list = Array.isArray(pending) ? pending : Array.isArray(pending?.data) ? pending.data : []
    const stillPending = list.some(
      (item: any) => (text(item?.id) ?? text(item?.requestID)) === requestID
    )
    if (!stillPending) return
  } catch {
    // Listing may be unavailable; relay anyway rather than hiding the request.
  }

  const resources = Array.isArray(data?.resources)
    ? data.resources.filter((item: unknown) => typeof item === "string" && item.length > 0)
    : []
  const decision = await askNotch(
    sessionID,
    text(data?.action) ?? "tool",
    resources as string[]
  )
  // null → notch is not running; "timeout" → let the terminal prompt take over.
  if (decision !== "allow" && decision !== "deny" && decision !== "always") return

  try {
    await ctx.permission.reply({
      sessionID,
      requestID,
      decision: decision === "always" ? "always" : decision === "allow" ? "once" : "reject",
    })
  } catch {
    // If the reply fails, the terminal prompt stays available.
  }
}

export default {
  id: "narra-notch",
  async setup(ctx: any) {
    const registrations: any[] = []
    const controller = new AbortController()

    // Ask the notch while OpenCode is still evaluating the action. Returning
    // `allow` here means no permission request is ever published, so the chat
    // UI never shows a second prompt after the notch/iPhone approved.
    let evaluateRegistered = false
    try {
      if (typeof ctx.permission?.hook === "function") {
        registrations.push(
          await ctx.permission.hook("evaluate", async (event: any) => {
            if (event?.effect !== "ask") return

            const action = text(event?.action)
            const sessionID = text(event?.sessionID)
            if (!action || !sessionID || !ASK_ACTIONS.has(action)) return

            const config = await runtimeConfig()
            if (!config.available || !config.enabled) return

            const resources = Array.isArray(event?.resources)
              ? (event.resources.filter(
                  (item: unknown) => typeof item === "string" && item.length > 0
                ) as string[])
              : []

            try {
              const decision = await askNotch(sessionID, action, resources, text(event?.source?.id))
              if (decision === "allow" || decision === "always") {
                event.effect = "allow"
                if (decision === "always") void rememberAlways(ctx, sessionID, action, resources)
              } else if (decision === "deny") {
                event.effect = "deny"
                event.message = "Ditolak melalui narra-notch"
              }
              // No decision (notch closed or timed out): leave `ask` in place so
              // OpenCode shows its own prompt instead of blocking forever.
            } catch {
              // Never break OpenCode's own approval flow from here.
            }
          })
        )
        evaluateRegistered = true
      }
    } catch {
      evaluateRegistered = false
    }

    try {
      registrations.push(
        await ctx.session.hook("prompt", (event: any) => {
          const sessionID = text(event?.sessionID)
          if (!sessionID) return
          const prompt = text(event?.prompt?.text) ?? ""
          void call("PreInvocation", {
            conversationId: sessionID,
            lastUserInput: prompt.slice(0, 500),
          })
          // Before the first tool can run: turn on approvals for this session.
          void syncSessionPermissions(ctx, sessionID)
        })
      )
    } catch {}

    try {
      registrations.push(
        await ctx.tool.hook("execute.before", (event: any) => {
          const sessionID = text(event?.sessionID)
          if (!sessionID) return
          void call("PreToolUse", {
            conversationId: sessionID,
            toolName: text(event?.tool) ?? "tool",
            args: normalizeInput(event?.input ?? event?.args),
          })
        })
      )
      registrations.push(
        await ctx.tool.hook("execute.after", (event: any) => {
          const sessionID = text(event?.sessionID)
          if (!sessionID) return
          void call("PostToolUse", { conversationId: sessionID })
        })
      )
    } catch {}

    const consume = async () => {
      for await (const item of ctx.event.subscribe({ signal: controller.signal })) {
        if (controller.signal.aborted) break
        const type = String(item?.type ?? "")
        const data: any = item?.data ?? {}
        const sessionID = text(data.sessionID) ?? text(data?.info?.id)

        if (type === "permission.asked" || type === "permission.v2.asked") {
          // The evaluate hook already resolved this on current servers.
          if (!evaluateRegistered) void relayApproval(ctx, data, sessionID)
          continue
        }
        if (!sessionID) continue

        if (
          type === "session.idle" ||
          type === "session.execution.succeeded" ||
          type === "session.execution.failed" ||
          type === "session.execution.interrupted"
        ) {
          void call("PostInvocation", { conversationId: sessionID })
        } else if (type === "session.error") {
          void call("Stop", { conversationId: sessionID })
        } else if (type === "session.status" || type === "session.execution.started") {
          const kind = data?.status?.type ?? (type === "session.execution.started" ? "busy" : "")
          if (kind === "busy" || kind === "retry") {
            void call("PreInvocation", { conversationId: sessionID })
            // Retries and resumed sessions may never hit the prompt hook again.
            void syncSessionPermissions(ctx, sessionID)
          }
        }
      }
    }

    const consuming = consume().catch(() => {})

    return async () => {
      controller.abort()
      try {
        await consuming
      } catch {}
      for (const registration of registrations) {
        try {
          await registration?.dispose?.()
        } catch {}
      }
    }
  },
}
